def can_place_flowers(flowerbed, n):
    bed = [0] + flowerbed[:] + [0]
    for index in range(1, len(bed) - 1):
        if bed[index-1] == bed[index] == bed[index+1] == 0:
            bed[index] = 1
            n -= 1
    return n <= 0

